// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, 1 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        uint256 balBefore = actor.balance;
        uint256 lockBlock = block.number + 1;

        // Lock is for a future block; current block is still before it.
        vm.prank(actor);
        bool ok; try c.settle() { ok = true; } catch { ok = false; }

        // Reference: settle must revert because block.number <= lockBlock.
        // Mutant: settle may execute immediately, wiping the lock and/or paying out.
        assertTrue(!ok && actor.balance == balBefore);
    }
}
